from pathlib import Pathimport jsonimport numpy as npimport pandas as pdimport matplotlib.pyplot as pltROOT = Path(__file__).resolve().parent.parentRAW = ROOT / 'data' / 'raw'PROCESSED = ROOT / 'data' / 'processed'RESULTS = ROOT / 'results'RESULTS.mkdir(exist_ok=True, parents=True)SAMPLE = RAW / 'multisat_2024_sample.csv'HISTORY = RAW / 'multisat_2024_gp_history.json'SATCAT = RAW / 'multisat_2024_satcat.json'PANEL = PROCESSED / 'multisat_2024_daily_decay_kp.csv'OUT = RESULTS / 'multisat_2024_classification.csv'SUMMARY = RESULTS / 'multisat_2024_classification_summary.csv'COVERAGE = RESULTS / 'multisat_2024_classification_coverage.csv'FIG = RESULTS / 'multisat_2024_classification.png'def mission_label(name):    """Simple name-based *candidate* labels; NEVER evidence of actual mission."""    s = str(name).upper()    if 'STARLINK' in s:        return 'Starlink (name-derived)'    if 'ONEWEB' in s:        return 'OneWeb (name-derived)'    if 'CIRBE' in s:        return 'CIRBE (name-derived)'    if 'FLOCK' in s or 'DOVE' in s:        return 'Flock/Dove (name-derived)'    return 'Unclassified mission'def incline_band(value):    if pd.isna(value):        return 'Unknown inclination'    if value < 30:        return '<30 deg'    if value < 70:        return '30-70 deg'    if value < 100:        return '70-100 deg'    return '>=100 deg'def main():    for path in (SAMPLE, HISTORY):        if not path.exists():            raise FileNotFoundError(f'Missing {path}; run download_multisat_2024.py first')    sample = pd.read_csv(SAMPLE)    sample.columns = sample.columns.str.strip()    sample['norad_id'] = pd.to_numeric(sample['NORAD_CAT_ID'], errors='coerce')    sample = sample.dropna(subset=['norad_id']).copy()    sample['norad_id'] = sample['norad_id'].astype(int)    sample = sample.drop_duplicates('norad_id')    sample = sample[['norad_id', 'OBJECT_NAME', 'altitude_km', 'altitude_band']].rename(        columns={'OBJECT_NAME': 'sample_name', 'altitude_km': 'sample_altitude_km', 'altitude_band': 'sample_altitude_band'})    gp = pd.DataFrame(json.loads(HISTORY.read_text(encoding='utf-8')))    needed = {'NORAD_CAT_ID', 'EPOCH', 'MEAN_MOTION'}    if not needed.issubset(gp.columns):        raise ValueError('GP history missing required columns: ' + str(needed - set(gp.columns)))    gp['norad_id'] = pd.to_numeric(gp['NORAD_CAT_ID'], errors='coerce')    gp['epoch'] = pd.to_datetime(gp['EPOCH'], errors='coerce', utc=True)    for name in ['MEAN_MOTION', 'INCLINATION', 'ECCENTRICITY']:        gp[name] = pd.to_numeric(gp[name], errors='coerce') if name in gp.columns else np.nan    gp = gp.dropna(subset=['norad_id', 'epoch', 'MEAN_MOTION'])    gp = gp[gp.MEAN_MOTION > 0].copy()    gp['norad_id'] = gp.norad_id.astype(int)    gp['altitude_km'] = (398600.4418 / (gp.MEAN_MOTION * 2 * np.pi / 86400)**2)**(1/3) - 6371    gp['date'] = gp.epoch.dt.floor('D')    # Reference values: median of the week BEFORE the major May 10-13 storm.    pre = gp[(gp.date >= '2024-05-01') & (gp.date < '2024-05-10')].copy()    reference = pre.groupby('norad_id').agg(        reference_altitude_km=('altitude_km','median'),        reference_inclination_deg=('INCLINATION','median'),        reference_eccentricity=('ECCENTRICITY','median'),        n_pre_storm_records=('epoch','size')    ).reset_index()    history_count = gp.groupby('norad_id').agg(n_gp_records=('epoch','size'),                                               first_epoch=('epoch','min'),                                               last_epoch=('epoch','max')).reset_index()    out = pd.DataFrame({'norad_id': sorted(gp.norad_id.unique())})    out = out.merge(sample, on='norad_id', how='left', validate='one_to_one')    out = out.merge(history_count, on='norad_id', how='left', validate='one_to_one')    out = out.merge(reference, on='norad_id', how='left', validate='one_to_one')    if SATCAT.exists():        satcat = pd.DataFrame(json.loads(SATCAT.read_text(encoding='utf-8')))        if 'NORAD_CAT_ID' in satcat:            satcat['norad_id'] = pd.to_numeric(satcat['NORAD_CAT_ID'], errors='coerce')            satcat = satcat.dropna(subset=['norad_id']).copy()            satcat['norad_id'] = satcat.norad_id.astype(int)            fields = ['norad_id'] + [s for s in ['SATNAME','OBJECT_TYPE','INTLDES','COUNTRY'] if s in satcat.columns]            satcat = satcat[fields].drop_duplicates('norad_id')            out = out.merge(satcat, on='norad_id', how='left', validate='one_to_one')    if 'SATNAME' in out:        out['satellite_name'] = out['SATNAME'].fillna(out['sample_name'])    else:        out['satellite_name'] = out['sample_name']    out['satellite_name'] = out['satellite_name'].fillna('Unknown')    out['mission_candidate_UNVERIFIED'] = out.satellite_name.map(mission_label)    out['inclination_band'] = out.reference_inclination_deg.map(incline_band)    out['altitude_band'] = pd.cut(out.reference_altitude_km,                                  [200, 350, 500, 650, 800],                                  labels=['200-350 km', '350-500 km', '500-650 km', '650-800 km'], right=False)    out['altitude_band'] = out.altitude_band.astype('string').fillna('Outside bands or missing')    # Unknowns are explicit, never inferred from name, orbit, or catalog owner.    out['propulsion_verified'] = 'Unknown'    out['mass_kg_verified'] = np.nan    out['projected_area_m2_verified'] = np.nan    out['specific_impulse_s_verified'] = np.nan    out['mission_cost_usd_verified'] = np.nan    out['mission_class_verified'] = 'Unknown'    if PANEL.exists():        panel = pd.read_csv(PANEL)        required = {'norad_id', 'date', 'decay_km_day'}        if required.issubset(panel.columns):            panel['date'] = pd.to_datetime(panel.date, utc=True, errors='coerce')            panel['norad_id'] = pd.to_numeric(panel.norad_id, errors='coerce')            panel['decay_km_day'] = pd.to_numeric(panel.decay_km_day, errors='coerce')            panel = panel[(panel.date >= '2024-05-01') & (panel.date <= '2024-05-21')]            # flags indicate odd rate changes, not confirmed maneuvers            panel['possible_maneuver_or_outlier'] = ((panel.decay_km_day < -0.10) |                                                      (panel.decay_km_day > 2.0))            flags = panel.groupby('norad_id').agg(                valid_decay_days=('decay_km_day','count'),                possible_maneuver_or_outlier_days=('possible_maneuver_or_outlier','sum')            ).reset_index()            out = out.merge(flags, on='norad_id', how='left', validate='one_to_one')    out.sort_values('norad_id').to_csv(OUT, index=False)    summary = out.groupby(['altitude_band','inclination_band'], dropna=False).agg(        satellites=('norad_id','nunique'),        median_altitude_km=('reference_altitude_km','median'),        median_inclination_deg=('reference_inclination_deg','median')    ).reset_index().sort_values(['altitude_band','inclination_band'])    summary.to_csv(SUMMARY, index=False)    coverage = pd.DataFrame({        'field': ['Reference altitude','Inclination','Eccentricity','Verified mass','Verified area','Verified propulsion','Verified mission type'],        'satellites_with_value': [out.reference_altitude_km.notna().sum(),out.reference_inclination_deg.notna().sum(),            out.reference_eccentricity.notna().sum(),out.mass_kg_verified.notna().sum(),            out.projected_area_m2_verified.notna().sum(),(out.propulsion_verified != 'Unknown').sum(),            (out.mission_class_verified != 'Unknown').sum()]    })    coverage['satellites_total'] = len(out)    coverage.to_csv(COVERAGE, index=False)    print(f'Unique historical objects: {len(out)}; sampled objects: {len(sample)}')    print('\nAltitude groups from pre-storm orbital histories:')    print(out.groupby('altitude_band', dropna=False).size().to_string())    print('\nInclination groups:')    print(out.groupby('inclination_band').size().to_string())    print('\nVerified metadata coverage:')    print(coverage.to_string(index=False))    print('\nPossible maneuver/outlier flags are NOT confirmed maneuvers.')    plot_counts = out.groupby('altitude_band').size().reindex(        ['200-350 km','350-500 km','500-650 km','650-800 km','Outside bands or missing'],fill_value=0)    fig, ax = plt.subplots(figsize=(10,5))    ax.bar(plot_counts.index, plot_counts.values)    ax.set(xlabel='Pre-storm approximate orbital altitude', ylabel='Number of sampled objects',           title='May 2024 sampled objects by altitude (not population representative)')    ax.tick_params(axis='x', rotation=20)    fig.tight_layout()    fig.savefig(FIG, dpi=250)    plt.close(fig)    for p in (OUT, SUMMARY, COVERAGE, FIG):        print('Saved:',p)if __name__ == '__main__':    main()